<?php
require __DIR__.'/config.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['remover']))unset($_SESSION['cart'][(int)$_POST['remover']]);if(isset($_POST['atualizar'])){foreach(($_POST['qtd']??[]) as $vid=>$qty){$vid=(int)$vid;$qty=max(0,min(20,(int)$qty));if($qty===0)unset($_SESSION['cart'][$vid]);else $_SESSION['cart'][$vid]=$qty;}}header('Location: carrinho.php');exit;}
$items=[];$subtotal=0;
foreach($_SESSION['cart']??[] as $vid=>$qty){$s=db()->prepare("SELECT v.*,p.nome,p.preco,p.preco_promocional,p.imagem_url,p.ativo FROM variantes_estoque v JOIN produtos p ON p.id=v.produto_id WHERE v.id=?");$s->execute([(int)$vid]);$r=$s->fetch();if(!$r||!$r['ativo'])continue;$r['qty']=$qty;$r['unit']=$r['preco_promocional']!==null?(float)$r['preco_promocional']:(float)$r['preco'];$r['line']=$r['unit']*$qty;$subtotal+=$r['line'];$items[]=$r;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Carrinho | Loja BY</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">BY</span><span>LOJA BY<small>SUA MARCA, SEU ESTILO</small></span></a><a href="index.php">Continuar comprando</a></header><main class="wrap"><h1>Seu carrinho</h1><?php if(isset($_GET['adicionado'])):?><div class="notice success">Produto adicionado ao carrinho.</div><?php endif?><?php if(!$items):?><div class="card empty">Seu carrinho está vazio.<br><br><a class="btn" href="index.php">Explorar produtos</a></div><?php else:?><form method="post" class="card"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Preço</th><th>Qtd.</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=h($it['nome'])?><br><small><?=h($it['tamanho'])?> · <?=h($it['cor'])?></small></td><td><?=money($it['unit'])?></td><td><input class="qty" type="number" min="0" max="20" name="qtd[<?=$it['id']?>]" value="<?=$it['qty']?>"></td><td><?=money($it['line'])?></td><td><button class="btn outline" name="remover" value="<?=$it['id']?>" formnovalidate>Remover</button></td></tr><?php endforeach?></tbody></table></div><p><button class="btn outline" name="atualizar">Atualizar carrinho</button></p><div style="text-align:right"><h2>Total parcial: <?=money($subtotal)?></h2><p class="muted">O frete será combinado/calculado na etapa de entrega.</p><a class="btn" href="checkout.php">Continuar para entrega</a></div></form><?php endif?></main><footer class="footer">LOJA BY</footer></body></html>
